// Notación UML de una clase:
// [NombreClase | -atributos: tipo | +Metodos(): tipo_retorno]

// Ejemplo:
[Jugador
 | -vida: int
 | -nombre: string
 | -posicion: Vector3
 | +TakeDamage(dano: int): void
 | +Morir(): void
 | +ObtenerVida(): int
]

// Visibilidad:
// + public     (visible desde fuera de la clase)
// - private    (solo visible dentro de la clase)
// # protected  (visible en la clase y sus subclases)

// En UML los attributes van en la sección media
// y los methods en la sección inferior.

// HERENCIA (inheritance): flecha hueca ──▷
// "Es un tipo de" (is-a)
// La subclase hereda attributes y methods de la superclase
Jugador ──▷ Personaje
Enemigo ──▷ Personaje

// COMPOSICIÓN (composition): diamante relleno ◆────
// "Parte imprescindible" (whole-part, strong ownership)
// Si el todo se destruye, la parte también
Juego ◆──── Nivel
Nivel ◆──── Enemigo

// AGREGACIÓN (aggregation): diamante vacío ◇────
// "Tiene" pero puede existir independientemente (weak ownership)
// Si el todo se destruye, la parte puede sobrevivir
Equipo ◇──── Jugador
Inventario ◇──── Item

// Las multiplicidades indican cuántos objetos
// participan en cada lado de la relación:

// 1      → exactamente uno
// 0..1   → cero o uno (opcional)
// *      → cero o más (many)
// 1..*   → uno o más (al menos uno)
// 2..5   → entre 2 y 5

// Ejemplos en un diagrama de videojuego:
Juego 1──────1..* Nivel     // Un Juego tiene al menos 1 Nivel
Jugador 1────0..1 Arma      // Un Jugador puede tener 0 o 1 Arma
Inventario 1─────* Item     // Un Inventario tiene 0 o más Items
Equipo 1─────2..4 Jugador   // Un Equipo tiene entre 2 y 4 jugadores

