// DIAGRAMA UML:
[EjecutorHabilidad | +EjecutarHabilidad(h: IHabilidad): void]
[IHabilidad | +Ejecutar(): void]  <<interface>>

EjecutorHabilidad - - ▷ IHabilidad

// CÓDIGO C#:
public class EjecutorHabilidad
{
    public void EjecutarHabilidad(IHabilidad h)
    {
        h.Ejecutar();
    }
}

